/* ---------- 6 · pricing ---------- */
.seo-price { display: flex; flex-direction: column; gap: 8px; max-width: 640px; }
.seo-price__row {
  display: flex; justify-content: space-between; align-items: baseline; gap: 20px;
  background: rgba(var(--glass),.5); border: 1px solid rgba(var(--hair),.07);
  border-radius: var(--radius-md); padding: 13px 18px;
}
.seo-price__name { font-weight: 700; font-size: 14px; }
.seo-price__val b { font-size: 15px; }
.seo-price__unit { color: var(--ink-3); font-size: 12px; }
.seo-price__val--quote { font-size: 12.5px; color: var(--ink-2); font-style: italic; text-align: right; }
.seo-price__cta { margin-top: 16px; }

/* wave 12 · pim.pricing[] rows — optional shortDescription line */
.seo-price__desc { display: block; font-size: 12px; font-weight: 400; color: var(--ink-3); margin-top: 2px; }
.seo-price__val { white-space: nowrap; } /* wave 12 — keep "displayPrice / interval" on one line */
